/******************************************************************************
 * Functions
 *****************************************************************************/

/**
 * @brief Resets the audio codec to its default state.
 *
 * This function initializes or reinitializes the codec registers and
 * internal state, ensuring that the codec is ready for operation.
 * It must be called after power-up to guarantee that the codec starts
 * in a defined state.
 *
 * @note The function should be called before starting audio streaming
 *       or when a codec error condition requires reinitialization.
 */
void codec_reset(void);

/**
 * @brief Initializes the codec and prepares the audio buffers for streaming.
 *
 * This function initializes the GPIOs, including their alternate functions
 * for the SAI interface, and enables the corresponding clock sources for
 * the ports. It also links the provided left and right channel buffers
 * for audio input/output.
 *
 * @param left_channel_buffer Pointer to the buffer for the left audio channel.
 * @param right_channel_buffer Pointer to the buffer for the right audio channel.
 * @param size Number of samples in each channel buffer.
 *
 * @return HAL status code indicating the result of the initialization.
 *         - HAL_OK: Initialization successful.
 *         - HAL_ERROR: Initialization failed.
 *
 * @note Must be called after `codec_reset()` and before `codec_start()`.
 */
HAL_StatusTypeDef codec_init(float32_t *left_channel_buffer,
                             float32_t *right_channel_buffer, uint32_t size);

/**
 * @brief Initializes and starts the SAI interface including DMA.
 *
 * This function configures the Serial Audio Interface (SAI) and the
 * associated DMA channels, then starts the audio data transfer.
 * It also enables the DMA interrupt for data reception, ensuring that
 * incoming audio data is handled properly.
 *
 * The DMA for both reception and transmission is implemented as a
 * ping-pong buffer and operates in endless (cyclic) mode.
 *
 * @note Must be called after codec_reset() to ensure the codec is in
 *       a defined state before starting audio transmission.
 */
void codec_start(void);

/**
 * @brief Checks if new audio data is available from the codec.
 *
 * This function should be called to determine whether the codec has
 * completed a data transfer and new audio samples are ready for
 * processing or copying.
 *
 * @return `true` if new audio data is available, `false` otherwise.
 *
 * @note Typically called immediately after the DMA interrupt or in
 *       the audio processing loop to ensure timely handling of data.
 */
uint8_t codec_data_ready(void);

/**
 * @brief Clears the data ready flag of the codec.
 *
 * This function should be called after polling `codec_data_ready()` and
 * processing the available audio data. It resets the internal flag,
 * allowing the codec and DMA to signal the next set of audio samples.
 *
 * @note Typically used in the audio processing loop immediately after
 *       handling the data.
 */
void codec_clear_data_ready(void);

/**
 * @brief Updates the audio output buffer for a specified channel.
 *
 * This function copies audio samples from the provided buffer into the
 * codec's output buffer for the selected channel. It is typically called
 * after new audio data is available and before the DMA transfers it to
 * the codec.
 *
 * @param channel The target channel to update (0 = left, 1 = right).
 * @param data Pointer to the buffer containing the audio samples to copy.
 * @param size Number of samples to copy from the `data` buffer.
 *
 * @note Should be called as soon as possible after `codec_data_ready()`
 *       returns true to ensure proper synchronization with the DMA transfer.
 */
void codec_update_output_buffer(uint8_t channel, float32_t *data, uint32_t size);

/**
 * @brief Copies the audio samples from the left I²S channel to the right channel.
 *
 * This function duplicates the left channel samples onto the right channel,
 * ensuring that both outputs contain identical audio data. The result is a
 * mono signal derived from the left channel, output to both stereo channels.
 * The function should be called immediately after codec data ready to ensure
 * that the data is copied before it is output.
 */
void codec_mirror_left_channel(void);

/**
 * @brief Checks if the right audio channel input is present based on ADC reading.
 *
 * This function reads the ADC value from PF8 (ADC3_IN6) which is connected to
 * the right audio input channel. It detects whether there is an active signal
 * by measuring deviation from the DC bias level (GND reference). The function
 * uses hysteresis and consecutive reading requirements to prevent false triggering.
 *
 * @return 1 if right channel is active (stereo mode), 0 if only left channel (mono mode).
 *
 * @note This function maintains internal state for hysteresis and requires
 *       multiple consecutive readings before switching modes to ensure stability.
 *       It is designed to be called periodically in the main audio processing loop.
 */
uint8_t codec_is_right_channel_present(void);

#endif
